mapper.select:
SELECT product_id, warehouse_id, position_id, quantity
FROM inventory
WHERE product_id = #{productId}

SELECT product_id, warehouse_id, position_id, quantity
FROM inventory
WHERE product_id = #{productId} AND warehouse_id = #{warehouseId}

SELECT product_id, warehouse_id, position_id, quantity
FROM inventory
WHERE product_id = #{productId}
  AND warehouse_id = #{warehouseId}
  AND (position_id = #{positionId} OR (#{positionId} IS NULL AND position_id IS NULL))

mapper.update:
UPDATE inventory SET quantity = #{quantity}
WHERE product_id = #{productId}
  AND warehouse_id = #{warehouseId}
  AND (position_id = #{positionId} OR (#{positionId} IS NULL AND position_id IS NULL))

mapper.select:
SELECT id, product_id AS productId, warehouse_id AS warehouseId,
       position_id AS positionId, type, amount, remark,
       operator_id AS operatorId, create_time AS createTime
FROM inventory_log

    AND product_id = #{productId}
    AND warehouse_id = #{warehouseId}
    AND position_id = #{positionId}

ORDER BY create_time DESC
LIMIT #{limit}
